mw.loader.using(['mediawiki.util','mediawiki.api'],function(){var urlParams=new URLSearchParams(window.location.search),processedIds=new Set(),api=new mw.Api();document.querySelectorAll('.wiki-template-form-dropdown, .wiki-template-form-submit, .wiki-template-form-clear').forEach(function(el){var label=el.className.match(/dropdown|submit|clear/);if(!el.closest('.wiki-template-form')){console.error('[Wiki Form Engine] Structural Error: Found an orphaned '+label+' outside of any ".wiki-template-form" container.');}});document.querySelectorAll('.wiki-template-form').forEach(function(form){var formId=form.getAttribute('id');if(!formId||/^\d+$/.test(formId)||processedIds.has(formId)){var err=!formId?'missing "id" attribute.':/^\d+$/.test(formId)?'purely numeric ID "'+formId+'" banned.':'duplicate ID "'+formId+'" collision.';console.error('[Wiki Form Engine] Configuration Error: '+err);return;}processedIds.add(formId);var dropdowns=form.querySelectorAll('.wiki-template-form-dropdown');var formIsActive=Array.from(urlParams.keys()).some(function(k){return k.indexOf(formId+'_')===0;});if(dropdowns.length>0&&!form.querySelector('.wiki-template-form-submit')){console.warn('[Wiki Form Engine] Warning in form "'+formId+'": Missing a ".wiki-template-form-submit" button.');}function purgeFormUrlParams(paramsObject){var toRemove=[];paramsObject.forEach(function(v,k){if(k.indexOf(formId+'_')===0)toRemove.push(k);});toRemove.forEach(function(k){paramsObject.delete(k);});}form.parentElement.querySelectorAll('.wiki-template-form-viewport').forEach(function(viewport){var blueprint=viewport.querySelector('.wiki-template-form-blueprint');var output=viewport.querySelector('.wiki-template-form-output')||document.createElement('div');if(!viewport.querySelector('.wiki-template-form-output')){output.className='wiki-template-form-output';viewport.appendChild(output);}if(blueprint&&output){var wikitext=blueprint.innerHTML||blueprint.textContent;var decoder=document.createElement('div');decoder.innerHTML=wikitext;decoder.querySelectorAll('span.mw-nowiki-text, typeof\\:mw\\:Nowiki').forEach(function(span){span.parentNode.replaceChild(document.createTextNode(span.textContent||span.innerText),span);});wikitext=decoder.textContent||decoder.innerText;if(/%PARAM(?::[^%]+)?%/g.test(wikitext)){var compiled=wikitext,missingParam=false;var tokens=Array.from(new Set(wikitext.match(/%PARAM(?::[^%]+)?%/g)||[]));tokens.forEach(function(token){var paramName=token==="%PARAM%"?viewport.getAttribute('data-wiki-dpl-param'):token.replace("%PARAM:","").replace("%","");var val=urlParams.get(formId+'_'+paramName);if(!formIsActive||!val||!val.trim()){missingParam=true;}else{compiled=compiled.replace(new RegExp(token.replace(/[-\/\\^$*+?.()|[\]{}]/g,'\\$&'),'g'),val);}});if(missingParam){if(!output.getAttribute('data-has-initial-content')){output.setAttribute('data-has-initial-content','true');}else{output.innerHTML='';}}else{output.innerHTML='<p>Loading...</p>';api.parse(compiled).done(function(html){output.innerHTML=html;}).fail(function(){output.innerHTML='<p style="color:red;">Error: The server failed to parse the compiled wikitext statement.</p>';});}}}});dropdowns.forEach(function(placeholder){var param=placeholder.getAttribute('data-wiki-template-form-dropdown-param');if(!param||!param.trim()){console.error('[Wiki Form Engine] Error in form "'+formId+'": Dropdown selector is missing or has a blank "data-wiki-template-form-dropdown-param" attribute.');return;}var rawOptions=placeholder.querySelectorAll('.wiki-template-form-dropdown-param-option');if(!rawOptions.length){console.error('[Wiki Form Engine] Error in form "'+formId+'": The dropdown wrapper for parameter "'+param+'" contains no options.');return;}var hasBlank=false,hasNonBlank=false;rawOptions.forEach(function(opt){var v=opt.getAttribute('data-value');if(!v||!v.trim())hasBlank=true;else hasNonBlank=true;});if(!hasBlank)console.warn('[Wiki Form Engine] Warning in form "'+formId+'": Dropdown "'+param+'" is missing an empty default placeholder (data-value="").');if(!hasNonBlank){console.error('[Wiki Form Engine] Error in form "'+formId+'": Dropdown "'+param+'" has a blank placeholder but is missing actual choices.');return;}var select=document.createElement('select');if(placeholder.className)select.className=placeholder.className.replace('wiki-template-form-dropdown','').trim();select.setAttribute('data-target-param',param);if(!hasBlank){var fallback=document.createElement('option');fallback.value="";fallback.innerText="-- Select --";select.appendChild(fallback);}var activeVal=urlParams.get(formId+'_'+param);rawOptions.forEach(function(rawOpt){var opt=document.createElement('option'),v=rawOpt.getAttribute('data-value')|| "";opt.value=v;opt.innerText=rawOpt.innerText||v;if(activeVal!==null&&v===activeVal)opt.selected=true;select.appendChild(opt);});placeholder.parentNode.replaceChild(select,placeholder);});form.querySelectorAll('.wiki-template-form-submit').forEach(function(btn){btn.style.cursor='pointer';btn.onclick=function(){var newParams=new URLSearchParams(window.location.search);purgeFormUrlParams(newParams);form.querySelectorAll('select[data-target-param]').forEach(function(select){if(select.value&&select.value.trim())newParams.set(formId+'_'+select.getAttribute('data-target-param'),select.value);});window.location.href=mw.util.getUrl(mw.config.get('wgPageName'))+'?'+newParams.toString();};});form.querySelectorAll('.wiki-template-clear, .wiki-template-form-clear').forEach(function(btn){btn.style.cursor='pointer';btn.onclick=function(){var newParams=new URLSearchParams(window.location.search);purgeFormUrlParams(newParams);window.location.href=mw.util.getUrl(mw.config.get('wgPageName'))+'?'+newParams.toString();};});});});